import 'package:flutter/material.dart';
import '../../core/database/database_helper.dart';

class CustomersScreen extends StatefulWidget{const CustomersScreen({super.key});@override State<CustomersScreen> createState()=>_CustomersState();}
class _CustomersState extends State<CustomersScreen>{final search=TextEditingController();final name=TextEditingController();final phone=TextEditingController();Future<void> add()async{if(name.text.trim().isEmpty)return;await DatabaseHelper.instance.insert('customers',{'name':name.text,'phone':phone.text,'address':'','balance':0,'created_at':DateTime.now().toIso8601String()});name.clear();phone.clear();setState((){});}Future<void> form(){return showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('إضافة عميل'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'اسم العميل')),TextField(controller:phone,decoration:const InputDecoration(labelText:'رقم الجوال'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:()async{await add();if(mounted)Navigator.pop(context);},child:const Text('حفظ'))]));}@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(12),children:[Align(alignment:Alignment.centerLeft,child:FilledButton.icon(onPressed:form,icon:const Icon(Icons.person_add),label:const Text('إضافة عميل'))),const SizedBox(height:10),TextField(controller:search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(labelText:'بحث عن عميل',prefixIcon:Icon(Icons.search),border:OutlineInputBorder())),FutureBuilder(future:DatabaseHelper.instance.all('customers'),builder:(c,s){final q=search.text.toLowerCase();final rows=(s.data??[]).where((r)=>r['name'].toString().toLowerCase().contains(q)).toList();return Column(children:rows.map((r)=>Card(child:ListTile(title:Text(r['name']),subtitle:Text(r['phone']??''),trailing:Wrap(children:[Text('${r['balance']??0} ر.س',style:TextStyle(color:(r['balance']??0)>=0?Colors.green:Colors.red)),IconButton(onPressed:()async{await DatabaseHelper.instance.delete('customers',r['id']);setState((){});},icon:const Icon(Icons.delete,color:Colors.red))]))).toList());})]);}
}
